src/docwork/review_pilot.py:
"""Explicit author-pilot timing, separate from extraction and approval state."""

from __future__ import annotations

import hashlib
import fcntl
import json
import math
import os
import tempfile
import threading
import time
import uuid
from pathlib import Path

from .review import ReviewBlocked, ReviewConflict, _now

PILOT_VERSION = "assisted-author-pilot-v1"


def durations(events: list[dict], idle_seconds: int) -> dict:
    """Reading counts until the declared idle cutoff; pause intervals never count."""
    active = idle = paused = 0.0
    prior = 0.0
    running = True
    if type(idle_seconds) is not int or not 1 <= idle_seconds <= 3600:
        raise ValueError("Invalid pilot idle cutoff")
    for event in events:
        offset = event["offset_seconds"]
        if type(offset) not in (float, int) or not math.isfinite(offset) or offset < prior:
            raise ValueError("Pilot clock moved backwards")
        gap = offset - prior
        if running:
            active += min(gap, idle_seconds)
            idle += max(0, gap - idle_seconds)
        else:
            paused += gap
        if event["kind"] == "pause":
            running = False
        elif event["kind"] == "resume":
            running = True
        prior = offset
    return {"active_seconds": round(active, 3), "idle_seconds": round(idle, 3),
            "paused_seconds": round(paused, 3), "elapsed_seconds": round(prior, 3)}


class ReviewPilot:
    def __init__(self, directory: Path, store, *, clock=time.monotonic):
        self.directory = directory.resolve(strict=True)
        self.store, self.clock = store, clock
        self.protocol = json.loads((self.directory / "protocol.json").read_text())
        if self.protocol["pilot_version"] != PILOT_VERSION:
            raise ValueError("Unknown review pilot protocol")
        if self.store.database != self.directory / "review.sqlite":
            raise ValueError("Pilot must use its dedicated review database")
        self.documents = {doc["document_id"]: doc for doc in self.protocol["documents"]}
        self.protocol_hash = hashlib.sha256((self.directory / "protocol.json").read_bytes()).hexdigest()
        self.path = self.directory / "timing.json"
        self.lock = threading.RLock()
        self.starts = {}
        self._lock_stream = (self.directory / ".pilot.lock").open("a")
        try:
            fcntl.flock(self._lock_stream.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError as exc:
            self._lock_stream.close()
            raise ReviewConflict("Another pilot server owns this session") from exc
        self.data = (json.loads(self.path.read_text()) if self.path.exists()
                     else {"pilot_version": PILOT_VERSION, "protocol_sha256": self.protocol_hash, "trials": []})
        if self.data["protocol_sha256"] != self.protocol_hash:
            raise ValueError("Timing evidence belongs to a different protocol")
        # Server-monotonic timing cannot bridge a restart or machine reboot.
        # Keep interrupted participants in the denominator rather than retiming.
        for trial in self.data["trials"]:
            if trial["status"] in ("RUNNING", "PAUSED"):
                trial["status"] = "ABANDONED"
                trial["abandon_reason"] = "server_restarted; unobserved interval excluded"
        self._save()

    def _save(self):
        temporary = None
        try:
            fd, name = tempfile.mkstemp(prefix=".timing-", dir=self.directory)
            temporary = Path(name)
            with os.fdopen(fd, "wb") as stream:
                stream.write((json.dumps(self.data, indent=2) + "\n").encode())
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary, self.path)
        except (OSError, ValueError):
            if self.path.exists():
                self.data = json.loads(self.path.read_text())
            raise
        finally:
            if temporary is not None:
                temporary.unlink(missing_ok=True)

    def close(self):
        if hasattr(self, "_lock_stream") and not self._lock_stream.closed:
            self._lock_stream.close()

    def __del__(self):
        self.close()

    def view(self) -> dict:
        with self.lock:
            trials = [{**trial, **durations(trial["events"], self.protocol["idle_cutoff_seconds"])}
                      for trial in self.data["trials"]]
            consumed = {trial["document_id"] for trial in trials}
            next_doc = next((doc for doc in self.protocol["documents"] if doc["document_id"] not in consumed), None)
            return {"pilot_version": PILOT_VERSION, "scheduled": len(self.documents),
                    "idle_cutoff_seconds": self.protocol["idle_cutoff_seconds"],
                    "next_document": next_doc, "trials": trials,
                    "scope": "Author assisted review of precomputed OCR/rules suggestions; no manual-entry comparison."}

    def start(self, document_id: str, actor: str) -> dict:
        if not actor.strip() or len(actor) > 100:
            raise ValueError("A reviewer audit label of at most 100 characters is required")
        with self.lock:
            if any(t["status"] in ("RUNNING", "PAUSED") for t in self.data["trials"]):
                raise ReviewConflict("A pilot trial is already open")
            if not self.view()["next_document"] or self.view()["next_document"]["document_id"] != document_id:
                raise ReviewConflict("Use the next declared pilot document; trials cannot be repeated")
            detail = self.store.get(document_id)
            if (detail["revision"] != 1 or detail["approval"] is not None or
                    detail["record_hash"] != self.documents[document_id]["initial_record_hash"]):
                raise ReviewConflict("Pilot candidate changed before timing began")
            trial = {"id": uuid.uuid4().hex, "document_id": document_id, "actor": actor,
                     "status": "RUNNING", "started_at": _now(), "initial_record_hash": detail["record_hash"],
                     "events": [{"id": uuid.uuid4().hex, "kind": "start", "offset_seconds": 0.0, "recorded_at": _now()}]}
            self.starts[trial["id"]] = self.clock()
            self.data["trials"].append(trial)
            self._save()
            return self.view()

    def guard(self, document_id: str, actor: str | None = None):
        with self.lock:
            trial = next((t for t in self.data["trials"] if t["document_id"] == document_id), None)
            if trial is None or trial["status"] != "RUNNING":
                raise ReviewBlocked("Start or resume this pilot trial before changing the record")
            if actor is not None and trial["actor"] != actor:
                raise ReviewConflict("Keep the same reviewer audit label during the trial")

    def guard_view(self, document_id: str):
        with self.lock:
            if not any(t["document_id"] == document_id for t in self.data["trials"]):
                raise ReviewBlocked("Start the declared pilot trial before opening its source or suggestions")

    def event(self, trial_id: str, kind: str, event_id: str) -> dict:
        if kind not in ("interaction", "pause", "resume", "finish", "abandon"):
            raise ValueError("Unknown pilot event")
        if not isinstance(event_id, str) or len(event_id) != 32 or any(c not in "0123456789abcdef" for c in event_id):
            raise ValueError("A hexadecimal event ID is required")
        with self.lock:
            trial = next((t for t in self.data["trials"] if t["id"] == trial_id), None)
            if trial is None:
                raise KeyError("Unknown pilot trial")
            previous = next((e for e in trial["events"] if e["id"] == event_id), None)
            if previous:
                if previous["kind"] != kind:
                    raise ReviewConflict("Pilot event ID reused with a different action")
                return self.view()
            if trial["status"] not in ("RUNNING", "PAUSED"):
                raise ReviewConflict("Pilot trial is already closed")
            if kind == "resume" and trial["status"] != "PAUSED":
                raise ReviewConflict("Trial is not paused")
            if kind in ("interaction", "pause", "finish") and trial["status"] != "RUNNING":
                raise ReviewConflict("Resume the trial first")
            final = None
            if kind == "finish":
                detail = self.store.get(trial["document_id"])
                if not detail["approval"] or detail["approval"]["actor"] != trial["actor"]:
                    raise ReviewBlocked("Approve the current revision with the trial reviewer label first")
                try:
                    exported, _ = self.store.exported_file(trial["document_id"], detail["revision"], "json", "invoice.json")
                except KeyError as exc:
                    raise ReviewBlocked("Create the approved JSON export before finishing") from exc
                payload = json.loads(exported)
                if payload["record_hash"] != detail["record_hash"]:
                    raise ReviewConflict("Export differs from the current approved record")
                history = self.store.history(trial["document_id"])
                final = {"revision": detail["revision"], "record_hash": detail["record_hash"],
                         "approval_hash": detail["approval"]["approval_hash"],
                         "export_sha256": hashlib.sha256(exported).hexdigest(),
                         "corrections": sum(e["kind"] == "field_edited" for e in history),
                         "acknowledgments": sum(e["kind"] == "issue_acknowledged" for e in history)}
            trial["events"].append({"id": event_id, "kind": kind,
                                    "offset_seconds": self.clock() - self.starts[trial_id], "recorded_at": _now()})
            if kind in ("pause", "resume", "finish", "abandon"):
                trial["status"] = {"pause": "PAUSED", "resume": "RUNNING", "finish": "COMPLETE", "abandon": "ABANDONED"}[kind]
            if final:
                trial["final"] = final
            self._save()
            return self.view()

src/docwork/review.py:
"""Durable, local review of trusted candidate records.

This layer accepts already parsed pages. Intake and parser isolation are separate
work; callers must not feed arbitrary uploaded documents to the Phase 0 OCR path.
"""

from __future__ import annotations

import csv
import hashlib
import io
import json
import os
import re
import sqlite3
import tempfile
import uuid
from collections.abc import Sequence
from contextlib import contextmanager
from dataclasses import asdict, replace
from datetime import datetime, timezone
from pathlib import Path

from .contracts import HEADER_FIELDS, REQUIRED_FIELDS, Box, DocumentPage, FieldValue, InvoiceRecord, LineItem, TextSpan, ValidationIssue
from .parser_protocol import PARSER_VERSION
from .review_priority import score_review_priority
from .validation import validate_invoice

POLICY_VERSION = "review-v1"
EXPORT_SCHEMA_VERSION = "export-v1"


class ReviewConflict(Exception):
    """The caller used a stale revision or an approval no longer applies."""


class ReviewBlocked(Exception):
    """A record still needs a human decision before approval or export."""


def _json(value: object) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def _hash(value: object) -> str:
    return hashlib.sha256(_json(value).encode("utf-8")).hexdigest()


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _field(data: dict) -> FieldValue:
    return FieldValue(
        value=data["value"], raw=data["raw"], evidence_ids=tuple(data.get("evidence_ids", ())),
        origin=data.get("origin", "observed"), missing_reason=data.get("missing_reason"),
    )


def record_from_dict(data: dict) -> InvoiceRecord:
    return InvoiceRecord(
        schema_version=data["schema_version"],
        fields={name: _field(value) for name, value in data["fields"].items()},
        line_items=tuple(LineItem(row_id=row["row_id"], **{
            name: _field(row[name]) for name in ("description", "quantity", "unit_price", "line_total", "tax")
        }) for row in data["line_items"]),
    )


def page_from_dict(data: dict) -> DocumentPage:
    return DocumentPage(
        number=data["number"], width_px=data["width_px"], height_px=data["height_px"],
        spans=tuple(TextSpan(
            id=span["id"], page=span["page"], text=span["text"],
            box=Box(**span["box"]) if span["box"] else None,
            method=span["method"], confidence=span.get("confidence"),
        ) for span in data["spans"]),
    )


def pages_from_json(encoded: str) -> tuple[DocumentPage, ...]:
    data = json.loads(encoded)
    return tuple(page_from_dict(page) for page in (data if isinstance(data, list) else [data]))


def pages_to_json(pages: Sequence[DocumentPage]) -> str:
    return _json([asdict(page) for page in pages])


def _issue_key(issue: dict) -> str:
    return f"{issue['code']}|{issue['path']}"


def _csv_text(value: str | None) -> str:
    if value is None:
        return ""
    # Spreadsheet programs may ignore leading whitespace before a formula.
    return "'" + value if value.lstrip().startswith(("=", "+", "-", "@", "\t", "\r")) else value


def _csv_number(value: str | None) -> str:
    if value is None:
        return ""
    return value if re.fullmatch(r"-?\d+(?:\.\d+)?", value) else _csv_text(value)


def _atomic_write(path: Path, content: bytes) -> str:
    path.parent.mkdir(parents=True, exist_ok=True)
    digest = hashlib.sha256(content).hexdigest()
    if path.exists() or path.is_symlink():
        if path.is_symlink() or not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != digest:
            raise ReviewConflict(f"Export path already holds different content: {path}")
        return digest
    fd, temp_name = tempfile.mkstemp(prefix=".writing-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as output:
            output.write(content)
            output.flush()
            os.fsync(output.fileno())
        try:
            os.link(temp_name, path)
        except FileExistsError:
            if path.is_symlink() or not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != digest:
                raise ReviewConflict(f"Export path already holds different content: {path}") from None
    finally:
        if os.path.exists(temp_name):
            os.unlink(temp_name)
    return digest


class ReviewStore:
    def __init__(self, database: Path, export_root: Path | None = None):
        self.database = database.resolve()
        self.export_root = (export_root or self.database.parent / "exports").resolve()
        self.database.parent.mkdir(parents=True, exist_ok=True)
        with self._connect() as db:
            db.executescript("""
                CREATE TABLE IF NOT EXISTS documents (
                    id TEXT PRIMARY KEY, source_sha256 TEXT NOT NULL, source_name TEXT NOT NULL,
                    page_json TEXT NOT NULL, current_revision INTEGER NOT NULL, created_at TEXT NOT NULL,
                    media_type TEXT, size_bytes INTEGER, object_relpath TEXT,
                    page_image_sha256 TEXT, page_image_relpath TEXT,
                    status TEXT NOT NULL DEFAULT 'REVIEW_READY'
                );
                CREATE TABLE IF NOT EXISTS revisions (
                    document_id TEXT NOT NULL, revision INTEGER NOT NULL, parent_revision INTEGER,
                    record_json TEXT NOT NULL, record_hash TEXT NOT NULL, issues_json TEXT NOT NULL,
                    actor TEXT NOT NULL, created_at TEXT NOT NULL,
                    PRIMARY KEY (document_id, revision),
                    FOREIGN KEY (document_id) REFERENCES documents(id)
                );
                CREATE TABLE IF NOT EXISTS decisions (
                    document_id TEXT NOT NULL, revision INTEGER NOT NULL, issue_key TEXT NOT NULL,
                    reason TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL,
                    PRIMARY KEY (document_id, revision, issue_key),
                    FOREIGN KEY (document_id, revision) REFERENCES revisions(document_id, revision)
                );
                CREATE TABLE IF NOT EXISTS approvals (
                    document_id TEXT NOT NULL, revision INTEGER NOT NULL, record_hash TEXT NOT NULL,
                    decision_hash TEXT NOT NULL, approval_hash TEXT NOT NULL,
                    actor TEXT NOT NULL, policy_version TEXT NOT NULL,
                    created_at TEXT NOT NULL, PRIMARY KEY (document_id, revision),
                    FOREIGN KEY (document_id, revision) REFERENCES revisions(document_id, revision)
                );
                CREATE TABLE IF NOT EXISTS exports (
                    document_id TEXT NOT NULL, revision INTEGER NOT NULL, format TEXT NOT NULL,
                    schema_version TEXT NOT NULL, manifest_json TEXT NOT NULL, created_at TEXT NOT NULL,
                    PRIMARY KEY (document_id, revision, format, schema_version),
                    FOREIGN KEY (document_id, revision) REFERENCES approvals(document_id, revision)
                );
                CREATE TABLE IF NOT EXISTS review_events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT, document_id TEXT NOT NULL,
                    revision INTEGER NOT NULL, kind TEXT NOT NULL, actor TEXT NOT NULL,
                    detail TEXT NOT NULL, created_at TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS extraction_runs (
                    document_id TEXT PRIMARY KEY, profile TEXT NOT NULL, model_id TEXT,
                    prompt_sha256 TEXT, parser_version TEXT NOT NULL, input_sha256 TEXT NOT NULL,
                    extra_issues_json TEXT NOT NULL, created_at TEXT NOT NULL,
                    FOREIGN KEY (document_id) REFERENCES documents(id)
                );
            """)
            # Preserve databases created by the first review prototype.
            columns = {row["name"] for row in db.execute("PRAGMA table_info(documents)")}
            for name, definition in (
                ("media_type", "TEXT"), ("size_bytes", "INTEGER"),
                ("object_relpath", "TEXT"), ("status", "TEXT NOT NULL DEFAULT 'REVIEW_READY'"),
                ("page_image_sha256", "TEXT"), ("page_image_relpath", "TEXT"),
            ):
                if name not in columns:
                    db.execute(f"ALTER TABLE documents ADD COLUMN {name} {definition}")

    @contextmanager
    def _connect(self):
        db = sqlite3.connect(self.database, timeout=10)
        db.row_factory = sqlite3.Row
        try:
            db.execute("PRAGMA foreign_keys=ON")
            db.execute("PRAGMA journal_mode=WAL")
            with db:
                yield db
        finally:
            db.close()

    @staticmethod
    def _event(db: sqlite3.Connection, document_id: str, revision: int, kind: str, actor: str, detail: str) -> None:
        db.execute("INSERT INTO review_events(document_id, revision, kind, actor, detail, created_at) VALUES (?,?,?,?,?,?)",
                   (document_id, revision, kind, actor, detail, _now()))

    @staticmethod
    def _current(db: sqlite3.Connection, document_id: str, expected_revision: int | None = None) -> sqlite3.Row:
        row = db.execute("SELECT * FROM documents WHERE id=?", (document_id,)).fetchone()
        if row is None:
            raise KeyError(f"Unknown document: {document_id}")
        if expected_revision is not None and row["current_revision"] != expected_revision:
            raise ReviewConflict(f"Current revision is {row['current_revision']}, expected {expected_revision}")
        return row

    @staticmethod
    def _revision(db: sqlite3.Connection, document_id: str, revision: int) -> sqlite3.Row:
        row = db.execute("SELECT * FROM revisions WHERE document_id=? AND revision=?", (document_id, revision)).fetchone()
        if row is None:
            raise KeyError(f"Unknown revision: {revision}")
        return row

    def ingest(self, source_sha256: str, source_name: str, page: DocumentPage, record: InvoiceRecord) -> str:
        if len(source_sha256) != 64 or any(c not in "0123456789abcdef" for c in source_sha256):
            raise ValueError("source_sha256 must be a lowercase SHA-256 hex digest")
        document_id = uuid.uuid4().hex
        record_data = record.to_dict()
        issues = [asdict(issue) for issue in validate_invoice(record, page)]
        with self._connect() as db:
            db.execute("INSERT INTO documents(id,source_sha256,source_name,page_json,current_revision,created_at,status) VALUES (?,?,?,?,?,?,?)",
                       (document_id, source_sha256, source_name, _json(asdict(page)), 1, _now(), "REVIEW_READY"))
            db.execute("INSERT INTO revisions VALUES (?,?,?,?,?,?,?,?)",
                       (document_id, 1, None, _json(record_data), _hash(record_data), _json(issues), "extractor", _now()))
            db.execute("INSERT INTO extraction_runs VALUES (?,?,?,?,?,?,?,?)",
                       (document_id, "ocr_rules", None, None, "trusted-fixture-tesseract",
                        _hash([asdict(page)]), "[]", _now()))
            self._event(db, document_id, 1, "candidate_created", "extractor", "")
        return document_id

    def _attach_candidate(self, db: sqlite3.Connection, document_id: str,
                          pages: Sequence[DocumentPage], record: InvoiceRecord, *,
                          profile: str = "ocr_rules", model_id: str | None = None,
                          prompt_sha256: str | None = None,
                          extra_issues: Sequence[ValidationIssue] = ()) -> None:
        if not pages or [page.number for page in pages] != list(range(1, len(pages) + 1)):
            raise ValueError("Candidate pages must be consecutive from page 1")
        span_ids = [span.id for page in pages for span in page.spans]
        if len(span_ids) != len(set(span_ids)):
            raise ValueError("Span IDs must be unique across the document")
        data = record.to_dict()
        issues = [asdict(issue) for issue in (*validate_invoice(record, pages), *extra_issues)]
        doc = self._current(db, document_id, 0)
        if doc["status"] not in ("RECEIVED", "PROCESSING"):
            raise ReviewConflict(f"Cannot attach candidate in status {doc['status']}")
        db.execute("INSERT INTO revisions VALUES (?,?,?,?,?,?,?,?)",
                   (document_id, 1, None, _json(data), _hash(data), _json(issues), "extractor", _now()))
        db.execute("INSERT INTO extraction_runs VALUES (?,?,?,?,?,?,?,?)",
                   (document_id, profile, model_id, prompt_sha256, PARSER_VERSION,
                    _hash([asdict(page) for page in pages]), _json([asdict(issue) for issue in extra_issues]), _now()))
        db.execute("UPDATE documents SET page_json=?, current_revision=1, status='REVIEW_READY' WHERE id=?",
                   (pages_to_json(pages), document_id))
        self._event(db, document_id, 1, "candidate_created", "extractor", "")

    def get(self, document_id: str, revision: int | None = None) -> dict:
        with self._connect() as db:
            doc = self._current(db, document_id)
            if doc["current_revision"] == 0:
                raise ReviewBlocked(f"Document is {doc['status']} and has no candidate record")
            selected = revision or doc["current_revision"]
            rev = self._revision(db, document_id, selected)
            pages = pages_from_json(doc["page_json"])
            extraction = db.execute("SELECT profile,model_id,prompt_sha256,parser_version,input_sha256,created_at FROM extraction_runs WHERE document_id=?",
                                    (document_id,)).fetchone()
            decisions = db.execute("SELECT issue_key, reason, actor, created_at FROM decisions WHERE document_id=? AND revision=? ORDER BY issue_key",
                                   (document_id, selected)).fetchall()
            approval = db.execute("SELECT * FROM approvals WHERE document_id=? AND revision=?", (document_id, selected)).fetchone()
            issues = json.loads(rev["issues_json"])
            return {
                "document_id": document_id, "source_sha256": doc["source_sha256"],
                "source_name": doc["source_name"], "page": asdict(pages[0]),
                "pages": [asdict(page) for page in pages],
                "extraction": dict(extraction) if extraction else None,
                "revision": selected, "current_revision": doc["current_revision"],
                "record": json.loads(rev["record_json"]), "record_hash": rev["record_hash"],
                "issues": issues, "review_priority": score_review_priority(issues),
                "decisions": [dict(row) for row in decisions],
                "approval": dict(approval) if approval else None,
            }

    def edit(self, document_id: str, expected_revision: int, path: str, value: str | None,
             actor: str, evidence_ids: tuple[str, ...] | None = None) -> int:
        if not actor.strip():
            raise ValueError("actor is required")
        with self._connect() as db:
            db.execute("BEGIN IMMEDIATE")
            doc = self._current(db, document_id, expected_revision)
            current = self._revision(db, document_id, expected_revision)
            record = record_from_dict(json.loads(current["record_json"]))
            pages = pages_from_json(doc["page_json"])
            parts = path.split(".")
            if len(parts) == 2 and parts[0] == "fields" and parts[1] in record.fields:
                old = record.fields[parts[1]]
                target = "header"
            elif len(parts) == 3 and parts[0] == "line_items" and parts[2] in ("description", "quantity", "unit_price", "line_total", "tax"):
                row = next((item for item in record.line_items if item.row_id == parts[1]), None)
                if row is None:
                    raise ValueError(f"Unknown row ID: {parts[1]}")
                old = getattr(row, parts[2])
                target = "row"
            else:
                raise ValueError(f"Unsupported field path: {path}")
            refs = old.evidence_ids if evidence_ids is None else evidence_ids
            unknown = set(refs) - {span.id for page in pages for span in page.spans}
            if unknown:
                raise ValueError(f"Unknown evidence IDs: {', '.join(sorted(unknown))}")
            revised = FieldValue(
                value=value, raw=old.raw, evidence_ids=refs,
                origin="reviewer", missing_reason="reviewer_marked_missing" if value is None else None,
            )
            if target == "header":
                fields = dict(record.fields)
                fields[parts[1]] = revised
                record = replace(record, fields=fields)
            else:
                rows = tuple(replace(item, **{parts[2]: revised}) if item.row_id == parts[1] else item
                             for item in record.line_items)
                record = replace(record, line_items=rows)
            new_revision = expected_revision + 1
            data = record.to_dict()
            run = db.execute("SELECT extra_issues_json FROM extraction_runs WHERE document_id=?", (document_id,)).fetchone()
            extra_issues = json.loads(run["extra_issues_json"]) if run else []
            issues = [asdict(issue) for issue in validate_invoice(record, pages)] + extra_issues
            db.execute("INSERT INTO revisions VALUES (?,?,?,?,?,?,?,?)",
                       (document_id, new_revision, expected_revision, _json(data), _hash(data), _json(issues), actor, _now()))
            db.execute("UPDATE documents SET current_revision=?, status='REVIEW_READY' WHERE id=?",
                       (new_revision, document_id))
            self._event(db, document_id, new_revision, "field_edited", actor, path)
            return new_revision

    def acknowledge(self, document_id: str, expected_revision: int, code: str, path: str,
                    reason: str, actor: str) -> None:
        if not reason.strip() or not actor.strip():
            raise ValueError("reason and actor are required")
        key = f"{code}|{path}"
        with self._connect() as db:
            db.execute("BEGIN IMMEDIATE")
            self._current(db, document_id, expected_revision)
            rev = self._revision(db, document_id, expected_revision)
            if db.execute("SELECT 1 FROM approvals WHERE document_id=? AND revision=?",
                          (document_id, expected_revision)).fetchone():
                raise ReviewConflict("Approved decisions are immutable; edit the record to create a new revision")
            issues = json.loads(rev["issues_json"])
            if not any(_issue_key(issue) == key and issue["blocking"] for issue in issues):
                raise ValueError(f"No blocking issue at {key}")
            db.execute("INSERT INTO decisions VALUES (?,?,?,?,?,?) ON CONFLICT(document_id,revision,issue_key) DO UPDATE SET reason=excluded.reason, actor=excluded.actor, created_at=excluded.created_at",
                       (document_id, expected_revision, key, reason, actor, _now()))
            self._event(db, document_id, expected_revision, "issue_acknowledged", actor, key)

    def approve(self, document_id: str, expected_revision: int, actor: str) -> dict:
        if not actor.strip() or actor == "extractor":
            raise ValueError("a human reviewer identity is required")
        with self._connect() as db:
            db.execute("BEGIN IMMEDIATE")
            doc = self._current(db, document_id, expected_revision)
            rev = self._revision(db, document_id, expected_revision)
            record = json.loads(rev["record_json"])
            absent = [name for name in REQUIRED_FIELDS if not (record["fields"][name]["value"] or "").strip()]
            if absent:
                raise ReviewBlocked(f"Required fields unresolved: {', '.join(absent)}")
            issues = json.loads(rev["issues_json"])
            decisions = [dict(row) for row in db.execute(
                "SELECT issue_key, reason, actor, created_at FROM decisions WHERE document_id=? AND revision=? ORDER BY issue_key",
                (document_id, expected_revision))]
            decided = {decision["issue_key"] for decision in decisions}
            pending = [_issue_key(issue) for issue in issues if issue["blocking"] and _issue_key(issue) not in decided]
            if pending:
                raise ReviewBlocked(f"Blocking issues unresolved: {', '.join(pending)}")
            existing = db.execute("SELECT * FROM approvals WHERE document_id=? AND revision=?",
                                  (document_id, expected_revision)).fetchone()
            if existing:
                if existing["actor"] != actor:
                    raise ReviewConflict(f"Revision already approved by {existing['actor']}")
                return {**dict(existing), "source_sha256": doc["source_sha256"]}
            payload = {
                "document_id": document_id, "revision": expected_revision,
                "record_hash": rev["record_hash"], "source_sha256": doc["source_sha256"],
                "decision_hash": _hash(decisions), "policy_version": POLICY_VERSION, "actor": actor,
            }
            approval_hash = _hash(payload)
            created_at = _now()
            db.execute("INSERT INTO approvals VALUES (?,?,?,?,?,?,?,?)",
                       (document_id, expected_revision, rev["record_hash"], payload["decision_hash"],
                        approval_hash, actor, POLICY_VERSION, created_at))
            db.execute("UPDATE documents SET status='APPROVED' WHERE id=?", (document_id,))
            self._event(db, document_id, expected_revision, "approved", actor, approval_hash)
            return {**payload, "approval_hash": approval_hash, "created_at": created_at}

    def export(self, document_id: str, format: str) -> dict:
        if format not in ("json", "csv"):
            raise ValueError("format must be json or csv")
        with self._connect() as db:
            db.execute("BEGIN IMMEDIATE")
            doc = self._current(db, document_id)
            revision = doc["current_revision"]
            rev = self._revision(db, document_id, revision)
            approved = db.execute("SELECT * FROM approvals WHERE document_id=? AND revision=?",
                                  (document_id, revision)).fetchone()
            if approved is None or approved["record_hash"] != rev["record_hash"]:
                raise ReviewConflict("Current revision has no matching approval")
            existing = db.execute("SELECT manifest_json FROM exports WHERE document_id=? AND revision=? AND format=? AND schema_version=?",
                                  (document_id, revision, format, EXPORT_SCHEMA_VERSION)).fetchone()
            if existing:
                manifest = json.loads(existing["manifest_json"])
                for file in manifest["files"]:
                    path = Path(file["path"])
                    if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != file["sha256"]:
                        raise ReviewConflict(f"Previously exported file is missing or changed: {path}")
                return manifest
            record = json.loads(rev["record_json"])
            issues = json.loads(rev["issues_json"])
            decisions = [dict(row) for row in db.execute("SELECT issue_key, reason, actor, created_at FROM decisions WHERE document_id=? AND revision=? ORDER BY issue_key",
                                                  (document_id, revision))]
            base = self.export_root / document_id / f"revision-{revision}"
            files: list[dict] = []
            if format == "json":
                extraction = db.execute("SELECT profile,model_id,prompt_sha256,parser_version,input_sha256,created_at FROM extraction_runs WHERE document_id=?",
                                        (document_id,)).fetchone()
                data = {
                    "schema_version": EXPORT_SCHEMA_VERSION, "document_id": document_id,
                    "revision": revision, "source_sha256": doc["source_sha256"],
                    "record_hash": rev["record_hash"], "approval_hash": approved["approval_hash"],
                    "decision_hash": approved["decision_hash"],
                    "record": record, "page": asdict(pages_from_json(doc["page_json"])[0]),
                    "pages": [asdict(page) for page in pages_from_json(doc["page_json"])],
                    "extraction": dict(extraction) if extraction else None,
                    "issues": issues, "decisions": decisions,
                }
                path = base / "invoice.json"
                digest = _atomic_write(path, (json.dumps(data, indent=2, ensure_ascii=False) + "\n").encode())
                files.append({"path": str(path), "sha256": digest})
            else:
                fields = record["fields"]
                header = io.StringIO(newline="")
                writer = csv.writer(header)
                writer.writerow(["document_id", "revision", *(
                    column for name in HEADER_FIELDS for column in
                    (name, f"{name}_origin", f"{name}_missing_reason", f"{name}_evidence_ids")
                )])
                writer.writerow([document_id, revision, *(
                    value for name in HEADER_FIELDS for value in (
                        _csv_number(fields[name]["value"]) if name in ("subtotal", "tax", "discount", "shipping", "total") else _csv_text(fields[name]["value"]),
                        fields[name]["origin"], fields[name]["missing_reason"] or "",
                        "|".join(fields[name]["evidence_ids"]),
                    )
                )])
                items = io.StringIO(newline="")
                writer = csv.writer(items)
                row_fields = ("description", "quantity", "unit_price", "line_total", "tax")
                writer.writerow(["document_id", "revision", "row_id", *(
                    column for name in row_fields for column in
                    (name, f"{name}_origin", f"{name}_missing_reason", f"{name}_evidence_ids")
                )])
                for row in record["line_items"]:
                    writer.writerow([document_id, revision, row["row_id"], *(
                        value for name in row_fields for value in (
                            _csv_text(row[name]["value"]) if name == "description" else _csv_number(row[name]["value"]),
                            row[name]["origin"], row[name]["missing_reason"] or "",
                            "|".join(row[name]["evidence_ids"]),
                        )
                    )])
                for name, content in (("header.csv", header.getvalue()), ("line-items.csv", items.getvalue())):
                    path = base / name
                    files.append({"path": str(path), "sha256": _atomic_write(path, content.encode("utf-8"))})
            manifest = {
                "document_id": document_id, "revision": revision, "format": format,
                "schema_version": EXPORT_SCHEMA_VERSION, "approval_hash": approved["approval_hash"],
                "decision_hash": approved["decision_hash"],
                "files": files,
            }
            db.execute("INSERT INTO exports VALUES (?,?,?,?,?,?)",
                       (document_id, revision, format, EXPORT_SCHEMA_VERSION, _json(manifest), _now()))
            self._event(db, document_id, revision, "exported", approved["actor"], format)
            return manifest

    def history(self, document_id: str) -> list[dict]:
        with self._connect() as db:
            self._current(db, document_id)
            return [dict(row) for row in db.execute("SELECT revision, kind, actor, detail, created_at FROM review_events WHERE document_id=? ORDER BY id", (document_id,))]

    def exported_file(self, document_id: str, revision: int, format: str, filename: str) -> tuple[bytes, str]:
        """Return only a file recorded by an immutable export manifest."""
        if filename not in ("invoice.json", "header.csv", "line-items.csv"):
            raise KeyError("Unknown export file")
        with self._connect() as db:
            self._current(db, document_id)
            row = db.execute(
                "SELECT manifest_json FROM exports WHERE document_id=? AND revision=? AND format=? AND schema_version=?",
                (document_id, revision, format, EXPORT_SCHEMA_VERSION),
            ).fetchone()
            if row is None:
                raise KeyError("Unknown export")
            manifest = json.loads(row["manifest_json"])
            entry = next((file for file in manifest["files"] if Path(file["path"]).name == filename), None)
            if entry is None:
                raise KeyError("File is not part of this export")
            path = Path(entry["path"])
            if not path.resolve().is_relative_to(self.export_root) or path.is_symlink() or not path.is_file():
                raise ReviewConflict("Export file is missing or replaced")
            content = path.read_bytes()
            if hashlib.sha256(content).hexdigest() != entry["sha256"]:
                raise ReviewConflict("Export file failed checksum verification")
            return content, "application/json" if filename.endswith(".json") else "text/csv; charset=utf-8"

src/docwork/web.py:
"""Loopback-only browser review prototype using the existing durable stores.

This zero-dependency interface is for local demonstrations. A random session
token and same-origin mutation checks protect against casual cross-site access;
actor names remain unauthenticated audit labels.
"""

from __future__ import annotations

import hashlib
import json
import re
import secrets
from http import HTTPStatus
from http.cookies import SimpleCookie
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs, unquote, urlsplit

from .baseline import extract_invoice
from .intake import IntakeStore
from .local_model import LocalModelConfig
from .ocr import MAX_FILE_BYTES, tesseract_page
from .review import ReviewBlocked, ReviewConflict
from .worker import process_one

DOCUMENT_ID = re.compile(r"[0-9a-f]{32}")
PAGE_ROUTE = re.compile(r"/api/documents/([0-9a-f]{32})/pages/([1-9]\d*)")
EXPORT_ROUTE = re.compile(r"/api/exports/([0-9a-f]{32})/(\d+)/(json|csv)/(invoice\.json|header\.csv|line-items\.csv)")
STATIC = {"/": ("index.html", "text/html; charset=utf-8"),
          "/app.js": ("app.js", "text/javascript; charset=utf-8"),
          "/pilot.js": ("pilot.js", "text/javascript; charset=utf-8"),
          "/style.css": ("style.css", "text/css; charset=utf-8")}
DEMO_FILES = {"clean": "clean.png", "conflicting-total": "conflicting-total.png"}


class ReviewServer(ThreadingHTTPServer):
    daemon_threads = True

    def __init__(self, address: tuple[str, int], store: IntakeStore, *, token: str | None = None,
                 model_config: LocalModelConfig | None = None, model_profile: str | None = None,
                 review_pilot=None, demo_replay: dict | None = None):
        if address[0] not in ("127.0.0.1", "::1"):
            raise ValueError("Review server must bind to loopback")
        self.store = store
        self.token = token or secrets.token_urlsafe(32)
        self.model_config = model_config
        self.model_profile = model_profile
        self.review_pilot = review_pilot
        if demo_replay is not None and (model_config is not None or review_pilot is not None):
            raise ValueError("Replay uses recorded candidates without a model or timed pilot")
        self.demo_replay = demo_replay
        self.repo_root = Path(__file__).resolve().parents[2]
        super().__init__(address, ReviewHandler)

    @property
    def origin(self) -> str:
        host = "[::1]" if self.server_address[0] == "::1" else "127.0.0.1"
        return f"http://{host}:{self.server_port}"


class ReviewHandler(BaseHTTPRequestHandler):
    server: ReviewServer

    def log_message(self, format: str, *args) -> None:
        # Avoid writing document names, field values, tokens, or query strings.
        pass

    def _send(self, status: int, body: bytes, media_type: str, *, headers: dict[str, str] | None = None) -> None:
        self.send_response(status)
        self.send_header("Content-Type", media_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("X-Frame-Options", "DENY")
        self.send_header("Content-Security-Policy", "default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self'; object-src 'none'; base-uri 'none'")
        for name, value in (headers or {}).items():
            self.send_header(name, value)
        self.end_headers()
        self.wfile.write(body)

    def _json(self, status: int, value: object) -> None:
        self._send(status, json.dumps(value, ensure_ascii=False).encode("utf-8"), "application/json; charset=utf-8")

    def _authorized(self) -> bool:
        cookie = SimpleCookie()
        try:
            cookie.load(self.headers.get("Cookie", ""))
        except Exception:
            return False
        session = cookie.get("docwork_session")
        return session is not None and secrets.compare_digest(session.value, self.server.token)

    def _read_body(self, maximum: int) -> bytes:
        raw = self.headers.get("Content-Length")
        if raw is None or not raw.isdecimal():
            raise ValueError("Content-Length is required")
        length = int(raw)
        if length < 1 or length > maximum:
            raise ValueError("Request body exceeds its allowed size")
        body = self.rfile.read(length)
        if len(body) != length:
            raise ValueError("Incomplete request body")
        return body

    def _input(self) -> dict:
        if self.headers.get("Content-Type", "").split(";", 1)[0] != "application/json":
            raise ValueError("Expected application/json")
        data = json.loads(self._read_body(64 * 1024))
        if not isinstance(data, dict):
            raise ValueError("Expected a JSON object")
        return data

    @staticmethod
    def _required(data: dict, key: str, expected: type):
        value = data.get(key)
        if type(value) is not expected:
            raise ValueError(f"{key} must be {expected.__name__}")
        return value

    @staticmethod
    def _document_route(path: str) -> tuple[str, str] | None:
        parts = path.split("/")
        if len(parts) not in (4, 5) or parts[:3] != ["", "api", "documents"] or not DOCUMENT_ID.fullmatch(parts[3]):
            return None
        return parts[3], parts[4] if len(parts) == 5 else ""

    def _handle_error(self, exc: Exception) -> None:
        if isinstance(exc, KeyError):
            status = HTTPStatus.NOT_FOUND
        elif isinstance(exc, ReviewConflict):
            status = HTTPStatus.CONFLICT
        elif isinstance(exc, ReviewBlocked):
            status = HTTPStatus.UNPROCESSABLE_ENTITY
        elif isinstance(exc, (ValueError, json.JSONDecodeError)):
            status = HTTPStatus.BAD_REQUEST
        else:
            status = HTTPStatus.INTERNAL_SERVER_ERROR
        message = str(exc) if status != HTTPStatus.INTERNAL_SERVER_ERROR else "Internal server error"
        self._json(status, {"error": message})

    def do_GET(self) -> None:
        url = urlsplit(self.path)
        if url.path == "/" and not self._authorized():
            candidate = parse_qs(url.query).get("token", [""])[0]
            if candidate and secrets.compare_digest(candidate, self.server.token):
                self.send_response(HTTPStatus.SEE_OTHER)
                self.send_header("Location", "/")
                self.send_header("Set-Cookie", f"docwork_session={self.server.token}; HttpOnly; SameSite=Strict; Path=/")
                self.send_header("Cache-Control", "no-store")
                self.end_headers()
                return
        if not self._authorized():
            self._json(HTTPStatus.UNAUTHORIZED, {"error": "Open the session URL printed by docwork serve"})
            return
        try:
            if url.path in STATIC:
                filename, media = STATIC[url.path]
                content = (self.server.repo_root / "ui" / filename).read_bytes()
                self._send(HTTPStatus.OK, content, media)
            elif url.path == "/api/documents":
                self._json(HTTPStatus.OK, self.server.store.list_documents())
            elif url.path == "/api/runtime":
                config = self.server.model_config
                self._json(HTTPStatus.OK, {"managed_model": config is not None,
                                          "model_id": config.model_id if config else None,
                                          "profile": self.server.model_profile,
                                          "demo_replay": getattr(self.server, "demo_replay", None),
                                          "review_pilot": getattr(self.server, "review_pilot", None) is not None})
            elif url.path == "/api/pilot" and getattr(self.server, "review_pilot", None) is not None:
                self._json(HTTPStatus.OK, self.server.review_pilot.view())
            elif match := EXPORT_ROUTE.fullmatch(url.path):
                doc_id, revision, format, filename = match.groups()
                content, media = self.server.store.exported_file(doc_id, int(revision), format, filename)
                self._send(HTTPStatus.OK, content, media, headers={"Content-Disposition": f'attachment; filename="{filename}"'})
            elif match := PAGE_ROUTE.fullmatch(url.path):
                self._page(match.group(1), int(match.group(2)))
            elif route := self._document_route(url.path):
                doc_id, action = route
                if action == "":
                    if getattr(self.server, "review_pilot", None) is not None:
                        self.server.review_pilot.guard_view(doc_id)
                    self._json(HTTPStatus.OK, self.server.store.get(doc_id))
                elif action == "status":
                    self._json(HTTPStatus.OK, self.server.store.status(doc_id))
                elif action == "history":
                    self._json(HTTPStatus.OK, self.server.store.history(doc_id))
                elif action == "page":
                    self._page(doc_id, 1)
                else:
                    self._json(HTTPStatus.NOT_FOUND, {"error": "Unknown route"})
            else:
                self._json(HTTPStatus.NOT_FOUND, {"error": "Unknown route"})
        except (KeyError, ValueError, OSError, ReviewConflict, ReviewBlocked) as exc:
            self._handle_error(exc)

    def _page(self, doc_id: str, number: int) -> None:
        if getattr(self.server, "review_pilot", None) is not None:
            self.server.review_pilot.guard_view(doc_id)
        if number > self.server.store.status(doc_id)["page_count"]:
            raise KeyError("Unknown page")
        try:
            page = self.server.store.page_image_path(doc_id, number)
        except ReviewConflict:
            status = self.server.store.status(doc_id)
            if number != 1 or status["page_image_sha256"] is not None:
                raise
            sample = next((name for name in DEMO_FILES.values()
                           if hashlib.sha256((self.server.repo_root / "samples" / name).read_bytes()).hexdigest() == status["source_sha256"]), None)
            if sample is None:
                raise KeyError("Rendered page is unavailable") from None
            page = self.server.repo_root / "samples" / sample
        self._send(HTTPStatus.OK, page.read_bytes(), "image/png")

    def do_POST(self) -> None:
        if not self._authorized():
            self._json(HTTPStatus.UNAUTHORIZED, {"error": "Session required"})
            return
        if self.headers.get("Origin") != self.server.origin:
            self._json(HTTPStatus.FORBIDDEN, {"error": "Same-origin request required"})
            return
        path = urlsplit(self.path).path
        try:
            pilot = getattr(self.server, "review_pilot", None)
            if getattr(self.server, "demo_replay", None) is not None and path in ("/api/upload", "/api/process-one", "/api/demo/seed"):
                raise ReviewBlocked("Replay uses recorded candidates. Start make dev for live processing.")
            elif path == "/api/pilot/start" and pilot is not None:
                data = self._input()
                self._json(HTTPStatus.CREATED, pilot.start(self._required(data, "document_id", str),
                                                          self._required(data, "actor", str)))
            elif path == "/api/pilot/event" and pilot is not None:
                data = self._input()
                self._json(HTTPStatus.OK, pilot.event(self._required(data, "trial_id", str),
                                                    self._required(data, "kind", str),
                                                    self._required(data, "event_id", str)))
            elif pilot is not None and path in ("/api/upload", "/api/process-one", "/api/demo/seed"):
                raise ReviewBlocked("The pilot uses its declared precomputed documents")
            elif path == "/api/upload":
                name = unquote(self.headers.get("X-File-Name", ""))
                media = self.headers.get("Content-Type", "")
                import io
                doc_id = self.server.store.submit(io.BytesIO(self._read_body(MAX_FILE_BYTES)), name, media)
                self._json(HTTPStatus.CREATED, self.server.store.status(doc_id))
            elif path == "/api/process-one":
                data = self._input()
                extractor = data.get("extractor", "ocr_rules")
                if extractor not in ("ocr_rules", "span_llm"):
                    raise ValueError("Unknown extractor profile")
                model_config = None
                if extractor == "span_llm":
                    configured = self.server.model_config
                    if configured is not None:
                        if "model_endpoint" in data or "model_id" in data:
                            raise ValueError("The managed model is selected by the server; omit endpoint overrides")
                        model_config = configured
                    else:
                        endpoint = self._required(data, "model_endpoint", str)
                        model_id = self._required(data, "model_id", str)
                        model_config = LocalModelConfig(endpoint, model_id)
                doc_id = process_one(self.server.store, "browser-worker", extractor=extractor,
                                     model_config=model_config)
                self._json(HTTPStatus.OK, self.server.store.status(doc_id) if doc_id else {"status": "IDLE"})
            elif path == "/api/demo/seed":
                fixture = self._required(self._input(), "fixture", str)
                if fixture not in DEMO_FILES:
                    raise ValueError("Unknown demo fixture")
                source = self.server.repo_root / "samples" / DEMO_FILES[fixture]
                page = tesseract_page(source)
                record = extract_invoice(page)
                doc_id = self.server.store.ingest(hashlib.sha256(source.read_bytes()).hexdigest(), source.name, page, record)
                self._json(HTTPStatus.CREATED, self.server.store.get(doc_id))
            elif route := self._document_route(path):
                doc_id, action = route
                data = self._input()
                if pilot is not None:
                    pilot.guard(doc_id, data.get("actor"))
                if action == "edit":
                    revision = self._required(data, "revision", int)
                    field_path = self._required(data, "path", str)
                    actor = self._required(data, "actor", str)
                    refs = data.get("evidence_ids")
                    if refs is not None and (not isinstance(refs, list) or not all(isinstance(value, str) for value in refs)):
                        raise ValueError("evidence_ids must be a string list")
                    value = data.get("value")
                    if value is not None and not isinstance(value, str):
                        raise ValueError("value must be text or null")
                    new_revision = self.server.store.edit(doc_id, revision, field_path, value,
                                                          actor, tuple(refs) if refs is not None else None)
                    self._json(HTTPStatus.OK, self.server.store.get(doc_id, new_revision))
                elif action == "acknowledge":
                    self.server.store.acknowledge(
                        doc_id, self._required(data, "revision", int), self._required(data, "code", str),
                        self._required(data, "path", str), self._required(data, "reason", str),
                        self._required(data, "actor", str),
                    )
                    self._json(HTTPStatus.OK, self.server.store.get(doc_id))
                elif action == "approve":
                    approval = self.server.store.approve(doc_id, self._required(data, "revision", int),
                                                         self._required(data, "actor", str))
                    self._json(HTTPStatus.OK, approval)
                elif action == "export":
                    manifest = self.server.store.export(doc_id, self._required(data, "format", str))
                    for file in manifest["files"]:
                        file["url"] = f"/api/exports/{doc_id}/{manifest['revision']}/{manifest['format']}/{Path(file['path']).name}"
                    self._json(HTTPStatus.OK, manifest)
                elif action == "retry":
                    self.server.store.retry(doc_id)
                    self._json(HTTPStatus.OK, self.server.store.status(doc_id))
                else:
                    self._json(HTTPStatus.NOT_FOUND, {"error": "Unknown route"})
            else:
                self._json(HTTPStatus.NOT_FOUND, {"error": "Unknown route"})
        except (KeyError, ValueError, OSError, ReviewConflict, ReviewBlocked) as exc:
            self._handle_error(exc)


def serve(database: Path, object_root: Path, port: int = 8765, *,
          model_config: LocalModelConfig | None = None, model_profile: str | None = None,
          demo_replay: dict | None = None) -> None:
    store = IntakeStore(database, object_root)
    with ReviewServer(("127.0.0.1", port), store,
                      model_config=model_config, model_profile=model_profile, demo_replay=demo_replay) as server:
        print(f"Open {server.origin}/?token={server.token}", flush=True)
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass

